#!/usr/bin/env bash
set -Eeuo pipefail

STAMP="$(date +%Y%m%d-%H%M%S)"
CTR="${TSP_BUILDER:-openmw_builder}"
SRC="/root/openmw-0.51-tsp-src"
BUILD="/root/openmw-0.51-tsp-build"
BUILT_BIN="$BUILD/openmw"
SRC_BACKUP="$SRC/.tsp-051-source-backups/visgrid-v20-door-bypass-$STAMP"

ROOT="/mnt/SDCARD/data/ports/openmw51"
BIN="$ROOT/bin/openmw-0.51"
LUA="$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua"
TOPO="$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/topology.lua"

PKG="$HOME/Downloads/openmw51-visgrid-v20-threshold-$STAMP"
LOG="$PKG/install.log"

V17_BIN_SHA="ce235c9e4cf1f4441106fd5445772710e072bf1c73c93a6cd409fdcd11e8caf3"
V19_SHA="01d52b059fcc3e61af0f503f1823d1881b142c336b288a0c13a4ba4a3e04a6d2"
V20_SHA="2ef92caeb5f8cdc8c95251aaa7fbe6332939a7cce6f242b752f6901c16becd9b"
TOPO_SHA="24a6989dacc1149a2a3895da371e56e52d370348d01ea0a5403f4e20755bef6b"
PATCHER_SHA="62b2ba2bcc03bc1f801d7e26e15751c0d0f03253eb26291c037fc1bde0c8f7f3"

mkdir -p "$PKG/device-backup" "$PKG/source"

if [ -f "$HOME/Downloads/visgrid-tools/device.env" ]; then
    . "$HOME/Downloads/visgrid-tools/device.env" || true
fi
if [ -n "${TSP_DEV:-}" ]; then DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then DEV="root@$TSP_IP"
else DEV="root@192.168.1.25"; fi
SSH=(-o BatchMode=yes -o ConnectTimeout=8)

PATCH_NEW=0
BUILD_OK=0
DEPLOY=0
REMOTE_BACKUP=""
NEW_BIN_SHA=""

restore_source() {
    set +e
    if docker exec "$CTR" test -s "$SRC_BACKUP/apps/openmw/mwrender/animation.cpp" 2>/dev/null; then
        echo "Restoring exact pre-V20 animation.cpp..."
        docker exec "$CTR" bash -lc "
          set -e
          cp -p '$SRC_BACKUP/apps/openmw/mwrender/animation.cpp' \
                '$SRC/apps/openmw/mwrender/animation.cpp'
        " || true
    fi
}

rollback_device() {
    set +e
    [ -n "$REMOTE_BACKUP" ] || return 1
    ssh "${SSH[@]}" "$DEV" "
      set -e
      test -s '$REMOTE_BACKUP/openmw-0.51.before-v20'
      test -s '$REMOTE_BACKUP/visgrid.lua.before-v20'
      cp -p '$REMOTE_BACKUP/openmw-0.51.before-v20' '$BIN'
      cp -p '$REMOTE_BACKUP/visgrid.lua.before-v20' '$LUA'
      chmod +x '$BIN'
      sync
    "
}

on_error() {
    rc=$?
    line=$1
    cmd=$2
    trap - ERR
    set +e
    [ "$DEPLOY" = 1 ] && rollback_device || true
    if [ "$PATCH_NEW" = 1 ] && [ "$BUILD_OK" != 1 ]; then
        restore_source || true
    fi
    {
      echo
      echo "=================================================================="
      echo "VISGRID V20 STOPPED SAFELY"
      echo "=================================================================="
      echo "Exit code: $rc"
      echo "Line: $line"
      echo "Command: $cmd"
      [ -f "$LOG" ] && { echo "----- install.log tail -----"; tail -220 "$LOG"; }
      [ -f "$PKG/build.log" ] && { echo "----- build.log tail -----"; tail -180 "$PKG/build.log"; }
      echo "Package preserved: $PKG"
      [ -n "$REMOTE_BACKUP" ] && echo "Device backup: $REMOTE_BACKUP"
      echo "=================================================================="
    } | tee "$PKG/STOPPED_ERROR.txt"
    exit "$rc"
}
trap 'on_error "$LINENO" "$BASH_COMMAND"' ERR
exec > >(tee "$LOG") 2>&1

echo "=================================================================="
echo "OPENMW 0.51 TSP — VISGRID V20 THRESHOLD LATCH + HARD DOOR BYPASS"
echo "=================================================================="
echo
echo "One small C++ rebuild:"
echo "  - real ESM doors bypass VISGRID depth culling globally"
echo "Lua:"
echo "  - symmetric two-room portal latches survive threshold crossings"
echo "  - near doorway + turn-around reopens the wedge immediately"
echo "  - actual mapped crossing gets 1.2s depth-curtain amnesty"
echo "  - structural PVS remains active the entire time"
echo "  - exact 6.0s load-safe hold preserved"
echo

command -v docker >/dev/null
command -v ssh >/dev/null
command -v scp >/dev/null
command -v python3 >/dev/null
