base64 -d "$PKG/visgrid-v20.lua.b64" > "$PKG/visgrid-v20.lua"
rm -f "$PKG/visgrid-v20.lua.b64"

cat > "$PKG/patch_v20_door_bypass.py.b64" <<'EOF_PATCH'
IyEvdXNyL2Jpbi9lbnYgcHl0aG9uMwpmcm9tIHBhdGhsaWIgaW1wb3J0IFBhdGgKaW1wb3J0IHN5
