base64 -d "$PKG/patch_v20_door_bypass.py.b64" > "$PKG/patch_v20_door_bypass.py"
rm -f "$PKG/patch_v20_door_bypass.py.b64"
chmod +x "$PKG/patch_v20_door_bypass.py"

test "$(sha256sum "$PKG/visgrid-v20.lua" | awk '{print $1}')" = "$V20_SHA"
test "$(sha256sum "$PKG/patch_v20_door_bypass.py" | awk '{print $1}')" = "$PATCHER_SHA"
grep -Fq 'TSP_VISGRID_LUA_V20_THRESHOLD_LATCH' "$PKG/visgrid-v20.lua"
grep -Fq 'TSP_VISGRID_V20_LOADSAFE_6S' "$PKG/visgrid-v20.lua"
grep -Fq 'POST_LOAD_ARM_DELAY = 6.0' "$PKG/visgrid-v20.lua"
python3 -m py_compile "$PKG/patch_v20_door_bypass.py"

cat > "$PKG/parsecheck.lua" <<'EOF_PARSE'
local f=arg[1]
local c,e=loadfile(f)
if not c then error(e) end
print("PARSE PASS "..f)
EOF_PARSE
if command -v luac >/dev/null 2>&1; then
    luac -p "$PKG/visgrid-v20.lua"
elif command -v lua >/dev/null 2>&1; then
    lua "$PKG/parsecheck.lua" "$PKG/visgrid-v20.lua"
elif command -v luatex >/dev/null 2>&1; then
    luatex --luaonly "$PKG/parsecheck.lua" "$PKG/visgrid-v20.lua"
fi
echo "PASS: exact V20 payloads verified."

echo
echo "===== 2/10 VERIFY DOCKER + DEVICE STATE ====="
docker inspect "$CTR" >/dev/null
if [ "$(docker inspect -f '{{.State.Running}}' "$CTR")" != "true" ]; then
    docker start "$CTR" >/dev/null
fi
docker exec "$CTR" test -d "$SRC"
docker exec "$CTR" test -d "$BUILD"

if ssh "${SSH[@]}" "$DEV" \
  'pidof openmw-0.51 >/dev/null 2>&1 || pidof openmw >/dev/null 2>&1'
then
    echo "ERROR: OpenMW is running. Exit normally, then rerun."
    exit 20
fi

LIVE_BIN="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$BIN'" | awk '{print $1}')"
LIVE_LUA="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$LUA'" | awk '{print $1}')"
LIVE_TOPO="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$TOPO'" | awk '{print $1}')"

echo "Device binary  : $LIVE_BIN"
echo "Device sensor  : $LIVE_LUA"
echo "Device topology: $LIVE_TOPO"

[ "$LIVE_TOPO" = "$TOPO_SHA" ] || {
    echo "ERROR: topology differs from tested Governor's Hall V1. ZERO changes."
    exit 21
}
if [ "$LIVE_LUA" != "$V19_SHA" ] && [ "$LIVE_LUA" != "$V20_SHA" ]; then
    echo "ERROR: sensor is neither exact V19 nor this exact V20. ZERO changes."
    exit 22
fi

PRE_DOCKER_BIN_SHA=""
if docker exec "$CTR" test -s "$BUILT_BIN"; then
    PRE_DOCKER_BIN_SHA="$(docker exec "$CTR" sha256sum "$BUILT_BIN" | awk '{print $1}')"
fi
if [ "$LIVE_BIN" != "$V17_BIN_SHA" ] && [ "$LIVE_BIN" != "$PRE_DOCKER_BIN_SHA" ]; then
    echo "ERROR: unknown device binary. ZERO source/device changes."
    exit 23
fi

ssh "${SSH[@]}" "$DEV" "grep -a -q 'TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS' '$BIN'"
echo "PASS: known PVS foundation verified."

echo
echo "===== 3/10 BACK UP + PATCH SOURCE ====="
docker cp "$PKG/patch_v20_door_bypass.py" "$CTR:/tmp/patch_v20_door_bypass.py"

set +e
PATCH_OUT="$(docker exec "$CTR" python3 /tmp/patch_v20_door_bypass.py "$SRC" "$SRC_BACKUP" 2>&1)"
PATCH_RC=$?
set -e
printf '%s\n' "$PATCH_OUT" | tee "$PKG/source-patch.log"

if [ "$PATCH_RC" -ne 0 ]; then
    exit "$PATCH_RC"
fi
if printf '%s\n' "$PATCH_OUT" | grep -Fq 'SOURCE_STATE=V20_PATCHED'; then
    PATCH_NEW=1
elif printf '%s\n' "$PATCH_OUT" | grep -Fq 'SOURCE_STATE=V20_ALREADY_PATCHED'; then
    PATCH_NEW=0
else
    echo "ERROR: patcher returned no recognized state."
    exit 24
fi

docker exec "$CTR" grep -Fq \
  'TSP_INTERIOR_VISGRID_051_V6_DOOR_BYPASS' \
  "$SRC/apps/openmw/mwrender/animation.cpp"
docker exec "$CTR" grep -Fq \
  '!mPtr.getClass().isDoor()' \
  "$SRC/apps/openmw/mwrender/animation.cpp"

if [ "$PATCH_NEW" = 1 ]; then
    ORIGINAL_SHA="$(docker exec "$CTR" sha256sum "$SRC_BACKUP/apps/openmw/mwrender/animation.cpp" | awk '{print $1}')"
    echo "Source backup SHA: $ORIGINAL_SHA"
    echo "PASS: source backup was byte-verified before mutation."
fi

echo
echo "===== 4/10 INCREMENTAL REBUILD ====="
PREBUILD_SHA=""
if docker exec "$CTR" test -s "$BUILT_BIN"; then
    PREBUILD_SHA="$(docker exec "$CTR" sha256sum "$BUILT_BIN" | awk '{print $1}')"
fi
echo "Pre-build SHA: $PREBUILD_SHA"

set +e
docker exec "$CTR" bash -lc \
  "cmake --build '$BUILD' --target openmw -j2" \
  > >(tee "$PKG/build.log") 2>&1
BUILD_RC=$?
set -e

if [ "$BUILD_RC" -ne 0 ]; then
    echo "ERROR: V20 build failed."
    [ "$PATCH_NEW" = 1 ] && restore_source
    exit "$BUILD_RC"
fi

docker exec "$CTR" test -s "$BUILT_BIN"
NEW_BIN_SHA="$(docker exec "$CTR" sha256sum "$BUILT_BIN" | awk '{print $1}')"
echo "Post-build SHA: $NEW_BIN_SHA"

if [ "$PATCH_NEW" = 1 ] && [ "$NEW_BIN_SHA" = "$PREBUILD_SHA" ]; then
    echo "ERROR: source changed but built binary SHA did not."
    restore_source
    exit 25
fi

docker exec "$CTR" bash -lc "
  set -e
  file '$BUILT_BIN'
  file '$BUILT_BIN' | grep -Eqi 'aarch64'
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS' '$BUILT_BIN'
"
BUILD_OK=1
echo "PASS: rebuilt AArch64 PVS binary."

echo
echo "===== 5/10 COPY V20 BINARY OUT TO UBUNTU ====="
docker cp "$CTR:$BUILT_BIN" "$PKG/openmw-0.51-v20"
test -s "$PKG/openmw-0.51-v20"
test "$(sha256sum "$PKG/openmw-0.51-v20" | awk '{print $1}')" = "$NEW_BIN_SHA"
chmod +x "$PKG/openmw-0.51-v20"
echo "PASS: Docker -> Ubuntu SHA verified."

echo
echo "===== 6/10 BACK UP EXACT DEVICE STATE ====="
REMOTE_BACKUP="$ROOT/backups/visgrid-v20-threshold-$STAMP"
ssh "${SSH[@]}" "$DEV" "
  set -e
  mkdir -p '$REMOTE_BACKUP'
  cp -p '$BIN' '$REMOTE_BACKUP/openmw-0.51.before-v20'
  cp -p '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v20'
  cp -p '$TOPO' '$REMOTE_BACKUP/topology.lua.before-v20'
  cmp -s '$BIN' '$REMOTE_BACKUP/openmw-0.51.before-v20'
  cmp -s '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v20'
  cmp -s '$TOPO' '$REMOTE_BACKUP/topology.lua.before-v20'
  sha256sum '$BIN' '$LUA' '$TOPO' > '$REMOTE_BACKUP/SHA256SUMS.before.txt'
  sync
"
scp "${SSH[@]}" -q "$DEV:$REMOTE_BACKUP/openmw-0.51.before-v20" "$PKG/device-backup/"
scp "${SSH[@]}" -q "$DEV:$REMOTE_BACKUP/visgrid.lua.before-v20" "$PKG/device-backup/"
test "$(sha256sum "$PKG/device-backup/openmw-0.51.before-v20" | awk '{print $1}')" = "$LIVE_BIN"
test "$(sha256sum "$PKG/device-backup/visgrid.lua.before-v20" | awk '{print $1}')" = "$LIVE_LUA"
echo "PASS: exact device backup verified on device + Ubuntu."

echo
echo "===== 7/10 STAGE + VERIFY ====="
scp "${SSH[@]}" -q "$PKG/openmw-0.51-v20" "$DEV:/tmp/openmw-0.51-v20"
scp "${SSH[@]}" -q "$PKG/visgrid-v20.lua" "$DEV:/tmp/visgrid-v20.lua"
test "$(ssh "${SSH[@]}" "$DEV" "sha256sum /tmp/openmw-0.51-v20" | awk '{print $1}')" = "$NEW_BIN_SHA"
test "$(ssh "${SSH[@]}" "$DEV" "sha256sum /tmp/visgrid-v20.lua" | awk '{print $1}')" = "$V20_SHA"
echo "PASS: staged binary + Lua verified."

echo
echo "===== 8/10 TRANSACTIONAL DEVICE INSTALL ====="
DEPLOY=1
ssh "${SSH[@]}" "$DEV" "
  set -e
  cp /tmp/openmw-0.51-v20 '$BIN.new'
  chmod +x '$BIN.new'
  mv -f '$BIN.new' '$BIN'

  cp /tmp/visgrid-v20.lua '$LUA.new'
  mv -f '$LUA.new' '$LUA'

  rm -f /tmp/openmw-0.51-v20 /tmp/visgrid-v20.lua
  sync
"
test "$(ssh "${SSH[@]}" "$DEV" "sha256sum '$BIN'" | awk '{print $1}')" = "$NEW_BIN_SHA"
test "$(ssh "${SSH[@]}" "$DEV" "sha256sum '$LUA'" | awk '{print $1}')" = "$V20_SHA"
test "$(ssh "${SSH[@]}" "$DEV" "sha256sum '$TOPO'" | awk '{print $1}')" = "$TOPO_SHA"
ssh "${SSH[@]}" "$DEV" "
  grep -Fq 'TSP_VISGRID_LUA_V20_THRESHOLD_LATCH' '$LUA'
  grep -Fq 'POST_LOAD_ARM_DELAY = 6.0' '$LUA'
"
DEPLOY=0
echo "PASS: V20 installed and SHA verified."

echo
echo "===== 9/10 WRITE HELPERS DIRECTLY IN ~/Downloads ====="
cat > "$HOME/Downloads/pull-visgrid-v20-threshold.sh" <<'EOF_PULL'
#!/usr/bin/env bash
set -Eeuo pipefail
ROOT="/mnt/SDCARD/data/ports/openmw51"

if [ -f "$HOME/Downloads/visgrid-tools/device.env" ]; then
    . "$HOME/Downloads/visgrid-tools/device.env" || true
fi
if [ -n "${TSP_DEV:-}" ]; then DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then DEV="root@$TSP_IP"
else DEV="root@192.168.1.25"; fi

SSH=(-o BatchMode=yes -o ConnectTimeout=8)
STAMP="$(date +%Y%m%d-%H%M%S)"
OUT="$HOME/Downloads/visgrid-v20-threshold-trace-$STAMP.txt"

{
    echo "=================================================================="
    echo "VISGRID V20 THRESHOLD-LATCH TRACE"
    echo "=================================================================="
    echo "Ubuntu date: $(date)"
    ssh "${SSH[@]}" "$DEV" 'date; hostname'

    echo
    echo "===== V20 / PVS / VISGRID ====="
    ssh "${SSH[@]}" "$DEV" "
      grep -hE \
        'TSP_VISGRID_V20|TSP_VISGRID_V11|TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS|TSP_INTERIOR_VISGRID|TSP_LOAD_FREEZE|Lua.*ERROR|Lua.*error' \
        '$ROOT/openmw_051_log.txt' '$ROOT/config-0.51/openmw.log' \
        2>/dev/null | tail -5600 || true
    "

    echo
    echo "===== PERF ====="
    ssh "${SSH[@]}" "$DEV" "
      [ -f '$ROOT/openmw51_perf_latest.txt' ] &&
        tail -1100 '$ROOT/openmw51_perf_latest.txt' || true
    "

    echo
    echo "===== HASHES ====="
    ssh "${SSH[@]}" "$DEV" "
      sha256sum \
        '$ROOT/bin/openmw-0.51' \
        '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua' \
        '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/topology.lua' \
        2>/dev/null || true
    "
} 2>&1 | tee "$OUT"

echo
echo "Saved directly in Downloads:"
echo "  $OUT"
EOF_PULL
chmod +x "$HOME/Downloads/pull-visgrid-v20-threshold.sh"
bash -n "$HOME/Downloads/pull-visgrid-v20-threshold.sh"

cat > "$HOME/Downloads/rollback-visgrid-v20-threshold.sh" <<'EOF_ROLL'
#!/usr/bin/env bash
set -Eeuo pipefail
ENV="$HOME/Downloads/v20-last-backup.env"
test -s "$ENV"
. "$ENV"

SSH=(-o BatchMode=yes -o ConnectTimeout=8)

if ssh "${SSH[@]}" "$DEV" \
  'pidof openmw-0.51 >/dev/null 2>&1 || pidof openmw >/dev/null 2>&1'
then
    echo "ERROR: exit OpenMW normally before rollback."
    exit 20
fi

ssh "${SSH[@]}" "$DEV" "
  set -e
  test -s '$REMOTE_BACKUP/openmw-0.51.before-v20'
  test -s '$REMOTE_BACKUP/visgrid.lua.before-v20'
  cp -p '$REMOTE_BACKUP/openmw-0.51.before-v20' '$BIN'
  cp -p '$REMOTE_BACKUP/visgrid.lua.before-v20' '$LUA'
  chmod +x '$BIN'
  sync
  sha256sum '$BIN' '$LUA'
"

echo "PASS: exact pre-V20 binary + sensor restored."
EOF_ROLL
